import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Button,
  Typography,
  CircularProgress,
  Box,
  Alert
} from '@mui/material';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';

const EmailSignInModal = ({ open, onClose, onEmailSubmit }) => {
  const [email, setEmail] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [verificationSent, setVerificationSent] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!email) {
      setError('Please enter your email address');
      return;
    }

    setIsSubmitting(true);
    setError('');

    try {
      // In development, use the Netlify dev server proxy
      const apiUrl = process.env.NODE_ENV === 'development' 
        ? '' // Relative URL will be handled by the proxy
        : process.env.REACT_APP_API_URL || ''; // Use the configured API URL in production
      const endpoint = `${apiUrl}/.netlify/functions/send-verification-email`;
      console.log('Sending request to:', endpoint);
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email }),
      });

      // First, check if the response is JSON
      const contentType = response.headers.get('content-type');
      let data;

      if (contentType && contentType.includes('application/json')) {
        data = await response.json();
      } else {
        // If not JSON, get the response as text for error handling
        const text = await response.text();
        console.error('Non-JSON response:', text);
        throw new Error('Received an invalid response from the server');
      }

      if (!response.ok) {
        console.error('API Error Response:', data);
        throw new Error(data.error || 'Failed to send verification email');
      }

      // Show success message
      setVerificationSent(true);

      // Store email in localStorage to pre-fill the booking form
      localStorage.setItem('pendingVerificationEmail', email);

    } catch (err) {
      console.error('Error in handleSubmit:', {
        message: err.message,
        stack: err.stack,
        name: err.name
      });

      // More specific error message based on error type
      let errorMessage = 'Failed to send verification email. Please try again later.';

      if (err.message.includes('Failed to fetch')) {
        errorMessage = 'Unable to connect to the server. Please check your internet connection.';
      } else if (err.message.includes('invalid response')) {
        errorMessage = 'Received an invalid response from the server. Please try again.';
      } else if (err.message) {
        errorMessage = err.message;
      }

      setError(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCloseModal = () => {
    setEmail('');
    setError('');
    setVerificationSent(false);
    onClose();
  };

  return (
    <Dialog open={open} onClose={handleCloseModal} maxWidth="sm" fullWidth>
      <DialogTitle>Sign In to Book an Appointment</DialogTitle>
      <form onSubmit={handleSubmit}>
        <DialogContent>
          {verificationSent ? (
            <Box textAlign="center" py={2}>
              <CheckCircleIcon color="success" sx={{ fontSize: 60, mb: 2 }} />
              <Typography variant="h6" gutterBottom>
                Check Your Email
              </Typography>
              <Typography variant="body1" color="text.secondary" paragraph>
                We've sent a verification link to <strong>{email}</strong>.
                Please check your inbox and click the link to continue booking your appointment.
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Didn't receive an email? Check your spam folder or try again.
              </Typography>
            </Box>
          ) : (
            <>
              <Typography variant="body1" gutterBottom>
                Enter your email address to receive a secure sign-in link.
              </Typography>
              <TextField
                autoFocus
                margin="dense"
                id="email"
                label="Email Address"
                type="email"
                fullWidth
                variant="outlined"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                disabled={isSubmitting}
                sx={{ mt: 2 }}
              />
              {error && (
                <Alert severity="error" sx={{ mt: 2 }}>
                  {error}
                </Alert>
              )}
            </>
          )}
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 3 }}>
          {!verificationSent && (
            <Button 
              onClick={handleCloseModal} 
              disabled={isSubmitting}
              variant="outlined"
            >
              Cancel
            </Button>
          )}
          <Button 
            type={verificationSent ? 'button' : 'submit'} 
            color="primary" 
            variant="contained"
            onClick={verificationSent ? handleCloseModal : undefined}
            disabled={isSubmitting}
            sx={{ minWidth: 120 }}
          >
            {isSubmitting ? (
              <CircularProgress size={24} />
            ) : verificationSent ? (
              'Close'
            ) : (
              'Send Verification Email'
            )}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  );
};

export default EmailSignInModal;
